// The program does not read the disk itself.
// It asks the kernel through a system call.
int fd = open("notes.txt", O_RDONLY);   // ask the OS to open a file
read(fd, buffer, 100);                    // ask the OS to read data
close(fd);                                // ask the OS to close it

